import sys
from itertools import product
MOD = 998244353
data = sys.stdin.read().split()
n = int(data[0]); m = int(data[1]); W = int(data[2])
claims = []
p = 3
for _ in range(m):
    claims.append((int(data[p]) - 1, int(data[p + 1]) - 1, int(data[p + 2])))
    p += 3
if W ** n <= 300000:
    count = 0
    for arr in product(range(1, W + 1), repeat=n):
        if all(max(arr[l:r + 1]) == v for l, r, v in claims):
            count += 1
    print(count % MOD)
    sys.exit()
# quadratic method: paint upper bounds, then count per value with a plain double loop
upper = [W + 1] * n
for l, r, v in claims:
    for i in range(l, r + 1):
        if v < upper[i]:
            upper[i] = v
for l, r, v in claims:
    if all(upper[i] != v for i in range(l, r + 1)):
        print(0)
        sys.exit()
groups = {}
for i in range(n):
    groups.setdefault(upper[i], []).append(i)
claims_by_value = {}
for l, r, v in claims:
    claims_by_value.setdefault(v, []).append((l, r))
ans = 1
for v, P in groups.items():
    k = len(P)
    if v == W + 1:
        ans = ans * pow(W, k, MOD) % MOD
        continue
    idx = {pos: t for t, pos in enumerate(P)}
    ivs = []
    for l, r in claims_by_value[v]:
        inside = [idx[i] for i in P if l <= i <= r]
        ivs.append((inside[0], inside[-1]))
    pw = [pow(v - 1, t, MOD) for t in range(k + 1)]
    # gap positions j..t are all below v; that is fine only if no interval lies inside j..t
    # first_ok[t] = smallest j allowed when the gap ends at t
    first_ok = [0] * k
    for t in range(k):
        first_ok[t] = max([a + 1 for a, b in ivs if b <= t], default=0)
    # g[i]: ways for the first i class positions with position i-1 equal to v
    g = [0] * (k + 1)
    g[0] = 1
    for i in range(1, k + 1):
        total = 0
        lo = first_ok[i - 2] if i >= 2 else 0
        for j in range(lo, i):
            total += g[j] * pw[i - 1 - j]
        g[i] = total % MOD
    total = 0
    lo = first_ok[k - 1]
    for j in range(lo, k + 1):
        total += g[j] * pw[k - j]
    ans = ans * (total % MOD) % MOD
print(ans)
